function dxfLine(a,b,layer){return `0\nLINE\n100\nAcDbEntity\n8\n${layer}\n100\nAcDbLine\n10\n${round(a.x,4)}\n20\n${round(a.y,4)}\n30\n0\n11\n${round(b.x,4)}\n21\n${round(b.y,4)}\n31\n0\n`;}
