      eng.capabilities={};eng.studioContext={};eng.taskLinks=[];eng.changeEvents=[];eng.unseenChangeSummary=null;eng.unseenChangeActor='';eng.changedObjectIds={nodes:new Set(),routes:new Set(),annotations:new Set()};
