    const emptyOverlay=!eng.snapshot.nodes.length?`<div class="engineering-empty-canvas cad-empty-start"><div class="cad-empty-start-card"><span>${icon('drafting',30)}</span><h3>${L('ابدأ أول رسمة في أقل من دقيقة','Start your first drawing in under a minute')}</h3><p>${L('اختَر عنصرًا من المكتبة وضعه على الشيت. بعد ذلك اربط العناصر بمسار، وOptimum سيحسب الحصر ويحفظ كل شيء تلقائيًا.','Choose an element from the library and place it on the sheet. Then connect elements with a route; Optimum will calculate takeoff and save everything automatically.')}</p><div><button class="btn btn-primary" data-action="engineering-guide-action" data-step="node">${icon('plus',14)} ${L('ضع أول عنصر','Place first element')}</button><button class="btn btn-secondary" data-action="engineering-network-wizard">${icon('wand',14)} ${L('ابنِ من جدول','Build from schedule')}</button><button class="btn btn-secondary" data-action="engineering-show-guide">${icon('help',14)} ${L('اشرح لي طريقة الرسم','Show me how')}</button></div></div></div>`:'';
