    const visible=eng.routeLibraryExpanded?groups:groups.slice(0,4),hidden=Math.max(0,groups.length-visible.length);
    const routeCard=([family,items])=>{items.sort((a,b)=>num(a.sort_order)-num(b.sort_order)||i18nLabel(a).localeCompare(i18nLabel(b),state.prefs.locale));const meta=familyMeta(family,items,true),chosen=items.find((item)=>item.code===(eng.routeFamilySelections[family]||''))||items[0];eng.routeFamilySelections[family]=chosen.code;return `<article class="cad-route-choice" style="--route-color:${e(catalogColor(chosen))}"><span class="cad-route-choice-line"></span><div><strong>${e(L(meta[0],meta[1]))}</strong><small>${e(i18nLabel(chosen))}</small></div><select data-eng-route-family-select="${e(family)}" aria-label="${e(L('نوع المسار','Route variant'))}">${selectOptions(items,(item)=>item.code,(item)=>i18nLabel(item),chosen.code)}</select><button draggable="true" class="btn btn-primary btn-sm" data-action="engineering-route-tool" data-code="${e(chosen.code)}" data-eng-drag-code="${e(chosen.code)}" data-eng-drag-kind="route">${icon('ruler',14)} ${L('ارسم','Draw')}</button></article>`;};
    return `<section class="engineering-quick-dock routes-only cad-master-route-dock cad-route-dock-r2"><div class="cad-resize-handle cad-resize-route" data-eng-resize="routes" title="${L('اسحب لتغيير ارتفاع مكتبة المسارات','Drag to resize route library')}"></div><div class="engineering-quick-dock-head"><div><strong>${L('المسارات — اختر النوع ثم ارسم','Routes — choose a type, then draw')}</strong><small>${L('نظهر الأنواع الأكثر استخدامًا أولًا. باقي الأنواع موجودة تحت «كل المسارات».','Common route families come first. The rest stay under “All routes”.')}</small></div><div class="engineering-dock-actions"><details class="cad-route-advanced"><summary>${icon('settings',13)} ${L('أدوات ترتيب','Layout tools')}</summary><div><button class="btn btn-secondary btn-sm" data-action="engineering-smart-routes">${icon('route',14)} ${L('ترتيب المسارات','Route optimizer')}</button><button class="btn btn-secondary btn-sm" data-action="engineering-auto-layout">${icon('layout',14)} ${L('ترتيب الشبكة','Network layout')}</button></div></details><button class="icon-btn" data-action="engineering-toggle-route-dock" title="${L('إخفاء المسارات','Hide routes')}">${icon('close',14)}</button></div></div><div class="cad-route-r2-grid">${visible.map(routeCard).join('')}${hidden?`<button class="cad-route-more" data-action="engineering-toggle-route-library">${icon(eng.routeLibraryExpanded?'chevronUp':'chevronDown',14)} ${eng.routeLibraryExpanded?L('إظهار الأساسية فقط','Show common only'):L(`كل المسارات (+${hidden})`,`All routes (+${hidden})`)}</button>`:eng.routeLibraryExpanded&&groups.length>4?`<button class="cad-route-more" data-action="engineering-toggle-route-library">${icon('chevronUp',14)} ${L('إظهار الأساسية فقط','Show common only')}</button>`:''}</div></section>`;
