    components.sort((a,b)=>b.length-a.length);const totalH=bounds.bottom-bounds.top,bandGap=46,availableH=totalH-bandGap*Math.max(0,components.length-1),totalNodes=Math.max(1,eng.snapshot.nodes.length);let bandTop=bounds.top;
    components.forEach((ids,componentIndex)=>{const bandH=Math.max(150,availableH*ids.length/totalNodes),nodes=ids.map((id)=>nodeMap.get(id));const degree=(id)=>(adj.get(id)||[]).length,roots=nodes.filter((n)=>['main'].includes(n.properties?.networkLevel||n.properties?.businessRole)||['main_cabinet','sub_cabinet','fdt'].includes(catalogItem(n.catalogCode)?.symbol_key)),root=(roots.sort((a,b)=>degree(b.id)-degree(a.id))[0])||nodes.sort((a,b)=>degree(b.id)-degree(a.id))[0];const levels=new Map([[root.id,0]]),queue=[root.id];while(queue.length){const id=queue.shift(),level=levels.get(id);for(const other of adj.get(id)||[]){if(ids.includes(other)&&!levels.has(other)){levels.set(other,level+1);queue.push(other);}}}nodes.filter((n)=>!levels.has(n.id)).forEach((n)=>levels.set(n.id,1));const grouped=new Map();nodes.forEach((n)=>{const level=levels.get(n.id)||0;if(!grouped.has(level))grouped.set(level,[]);grouped.get(level).push(n);});const levelKeys=[...grouped.keys()].sort((a,b)=>a-b),usableW=bounds.right-bounds.left;levelKeys.forEach((level,col)=>{const tier=grouped.get(level).sort((a,b)=>String(a.properties?.boxNo||a.label).localeCompare(String(b.properties?.boxNo||b.label),undefined,{numeric:true})),x=levelKeys.length===1?bounds.left+usableW/2:bounds.left+usableW*col/Math.max(1,levelKeys.length-1);tier.forEach((node,row)=>{node.x=x;node.y=bandTop+bandH*(row+1)/(tier.length+1);node.labelOffset={x:0,y:0};});});bandTop+=bandH+bandGap;});
    const lanes=new Map();eng.snapshot.routes.forEach((route,index)=>{syncRouteEndpoints(route,{infer:false});const a=nodeById(route.sourceNodeId),b=nodeById(route.targetNodeId);if(!a||!b)return;const horizontal=Math.abs(b.x-a.x)>=Math.abs(b.y-a.y),key=horizontal?`h:${Math.round((a.y+b.y)/70)}`:`v:${Math.round((a.x+b.x)/70)}`,lane=lanes.get(key)||0;lanes.set(key,lane+1);const direction=lane%2===0?1:-1,offset=direction*Math.ceil(lane/2)*32;if(horizontal){const mx=(a.x+b.x)/2;route.points=[{x:a.x,y:a.y},{x:mx,y:a.y+offset},{x:mx,y:b.y+offset},{x:b.x,y:b.y}];}else{const my=(a.y+b.y)/2;route.points=[{x:a.x,y:a.y},{x:a.x+offset,y:my},{x:b.x+offset,y:my},{x:b.x,y:b.y}];}route.properties.pathStyle='orthogonal';const labelSide=(index%2?1:-1);route.labelOffset={x:labelSide*38,y:-28-(index%3)*22};});
    eng.selected=null;eng.dirty=true;eng.pendingView={type:'fit'};render();toast('success',L('تم ترتيب الشبكة في طبقات واضحة مع فصل المسارات والبيانات','Network arranged in clear layers with separated routes and labels'));return true;
