    eng.snapshot.routes.forEach((route,index)=>{if(route.properties?.layoutLocked)return;const source=nodeById(route.sourceNodeId),target=nodeById(route.targetNodeId);if(!source||!target)return;const horizontal=Math.abs(target.x-source.x)>=Math.abs(target.y-source.y),key=horizontal?`h:${Math.round((source.y+target.y)/80)}`:`v:${Math.round((source.x+target.x)/80)}`,lane=lanes.get(key)||0;lanes.set(key,lane+1);const centered=lane===0?0:(lane%2?1:-1)*Math.ceil(lane/2)*34;if(horizontal){const midX=(source.x+target.x)/2;route.points=[nodeCenter(source),{x:midX,y:source.y+centered},{x:midX,y:target.y+centered},nodeCenter(target)];}else{const midY=(source.y+target.y)/2;route.points=[nodeCenter(source),{x:source.x+centered,y:midY},{x:target.x+centered,y:midY},nodeCenter(target)];}route.properties.pathStyle='orthogonal';route.labelOffset={x:(index%2?1:-1)*(32+(index%3)*18),y:-30-(index%2)*24};});
