  async function saveDrawingLocally(){
    const d=currentDrawing(),r=currentRevision(),payload=buildExportPayload('svg');if(!payload)return;
    try{
      if(window.showSaveFilePicker){
        const handle=await window.showSaveFilePicker({suggestedName:payload.filename,types:[{description:'SVG drawing',accept:{'image/svg+xml':['.svg']}}]});
        const writable=await handle.createWritable();await writable.write(payload.blob);await writable.close();
      }else downloadBlob(payload.blob,payload.filename);
      toast('success',L('تم حفظ ملف الرسم في المكان الذي اخترته','Drawing file saved to the selected location'));
    }catch(err){if(err?.name!=='AbortError')formError(err,L('تعذر حفظ الملف','Could not save file'));}
  }

