  if(draftOnlyForms.has(type)&&!isEditableRevision()){toast('info',L('هذه النسخة للقراءة فقط؛ استخدم «تعديل كمراجعة جديدة» أولًا','This version is read-only; use “Edit as new revision” first'));return true;}
  if(type==='engineering-new'){let result;try{result=await api.rpc('create_engineering_drawing_v2',{p_company_id:state.companyId,p_project_id:data.project_id,p_site_id:data.site_id||null,p_cabinet_id:data.cabinet_id||null,p_folder_id:data.folder_id||null,p_drawing_no:data.drawing_no,p_title:data.title,p_discipline:data.discipline,p_drawing_type:data.drawing_type,p_snapshot:normalizeEngineeringSnapshot(),p_sheet_settings:sheetDefaults()});}catch(err){result=await api.rpc('create_engineering_drawing',{p_company_id:state.companyId,p_project_id:data.project_id,p_site_id:data.site_id||null,p_folder_id:data.folder_id||null,p_drawing_no:data.drawing_no,p_title:data.title,p_discipline:data.discipline,p_drawing_type:data.drawing_type,p_snapshot:normalizeEngineeringSnapshot(),p_sheet_settings:sheetDefaults()});}if(data.source_document_id)await api.rpc('link_engineering_document',{p_drawing_id:result.drawing_id,p_revision_id:result.revision_id,p_document_id:data.source_document_id,p_relation_type:'source'});closeOverlay();await load();await openDrawing(result.drawing_id,result.revision_id);await syncDrawingToCde({silent:true});toast('success',L('تم إنشاء الرسم وحفظه وربطه بالسياق','Drawing created, saved and linked to its context'));}
