    syncRouteEndpoints(route,{infer:true});eng.snapshot.routes.push(route);eng.selected={kind:'route',id:route.id};eng.pendingRoute=null;eng.routeDraft=null;eng.connectSourceId=null;eng.tool='select';eng.sideTab='properties';closeOverlay();render();toast('success',L('تم إنشاء المسار وربطه بالحصر','Route created and linked to takeoff'));
